fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    // Ensure that k is within the valid range
    assert!(k >= 2 && k <= s.len(), "k must be at least 2 and at most the length of the array");

    let mut left = 0;
    let mut right = k - 1;

    // Reverse the first k elements in place
    while left < right {
        s.swap(left, right);
        left += 1;
        right -= 1;
    }
}